et.', 'Smoking is harmful to your health.'), ('fryse', 'word', '6b44477e-6bcd-5aae-ab23-a5eea2ea9ee9', 1, 'verb', null, 'to be cold, to freeze', 'Jeg fryser om vinteren.', 'I feel cold in winter.'), ('fryse', 'word', '55704781-5931-5249-abdf-4b778e1b05a3', 2, 'verb', null, 'to freeze (food)', 'Hun fryser resterne af maden.', 'She freezes the leftover food.'), ('konstruktiv', 'word', '36ac13bd-cc65-5817-851c-3a228c848ceb', 1, 'adjective', null, 'constructive', 'Det var en konstruktiv samtale.', 'It was a constructive conversation.'), ('støj', 'word', 'ee94e1c3-7246-5995-bbac-37f71737f071', 1, 'noun', 'en', 'noise', 'Der er meget støj fra vejen.', 'There is a lot of noise from the road.'), ('e', 'word', '30fe18c9-0f8f-5189-882c-1e20f53c941c', 1, 'noun', 'et', 'letter E', 'Ordet ender på et e.', 'The word ends in an E.'), ('indvandring', 'word', 'e6348f38-1f2f-5bfb-9a81-283a099529d3', 1, 'noun', 'en', 'immigration', 'Indvandring er et vigtigt emne i valgkampen.', 'Immigration is an important topic in the election campaign.'), ('velfærdssamfund', 'word', '3759d518-d7b8-5ea9-b583-c77ddc575d16', 1, 'noun', 'et', 'welfare society, welfare state', 'Danmark er kendt som et velfærdssamfund.', 'Denmark is known as a welfare society.'), ('sympati', 'word', '7ae0cc8f-c73a-5598-82dd-c891ed76b820', 1, 'noun', 'en', 'sympathy', 'Hun har stor sympati for ham.', 'She has great sympathy for him.'), ('grafik', 'word', '1924e7c0-c5b9-5a5c-a4fd-86c404b4c7db', 1, 'noun', 'en', 'graphics', 'Spillet har flot grafik.', 'The game has great graphics.'), ('vending', 'word', '7a8863f8-c96b-5708-a4d7-c9b614d7d68a', 1, 'noun', 'en', 'turn of phrase, expression', 'Det er en fast vending på dansk.', 'It is a set expression in Danish.'), ('regulering', 'word', '3b6d1edb-452b-5da5-8602-5a204b4671b1', 1, 'noun', 'en', 'regulation', 'Der er behov for bedre regulering af markedet.', 'There is a need for better regulation of the market.'), ('kørekort', 'word', '81b859be-4151-5c02-85e6-319ec6a73837', 1, 'noun', 'et', 'driving licence', 'Han fik sit kørekort sidste år.', 'He got his driving licence last year.'), ('undervisningsminister', 'word', '82192c95-d34d-5cb7-b2b3-f17b6fefba3d', 1, 'noun', 'en', 'minister of education', 'Undervisningsministeren besøgte skolen.', 'The minister of education visited the school.'), ('abort', 'word', '82fa1e7f-edfc-585c-9eb9-ca6876df6485', 1, 'noun', 'en', 'abortion', 'Hun overvejede en abort.', 'She was considering an abortion.'), ('pensionere', 'word', 'c09d36f9-03d9-5434-a04b-ec6e4ffe6567', 1, 'verb', null, 'to retire, to pension off', 'Han blev pensioneret i en alder af 65.', 'He was retired at the age of 65.'), ('skål', 'word', 'ac63da40-d7bd-58bf-839b-1b4c1fe2fd8c', 1, 'noun', 'en', 'bowl', 'Hun hælder suppen i en skål.', 'She pours the soup into a bowl.'), ('skål', 'word', 'e9c3e520-2703-5b23-a839-0ab881963bff', 2, 'noun', 'en', 'toast (drinking)', 'Vi udbragte en skål for brylluppet.', 'We proposed a toast to the wedding.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
